{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    for s in segments:
        for key in ['name','importance','minimum','capacity']:
            if key not in s:
                return {'error': f'missing field {key}'}
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        return {'error': 'budget out of range'}
    n = len(segments)
    allocated = [s['minimum'] for s in segments]
    total = min_sum
    while total < budget:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            if allocated[i] < s['capacity']:
                next_pos = allocated[i] + 1
                score = s['importance'] / next_pos
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        allocated[best_idx] += 1
        total += 1
    allocations = [{'name': segments[i]['name'], 'tokens': allocated[i]} for i in range(n)]
    name_mapping = {i: segments[i]['name'] for i in range(n)}
    conserved_total = total
    return {'allocations': allocations, 'name_mapping': name_mapping, 'conserved_total': conserved_total}"}
